css:
body {
    margin: 0;
    padding: 0;
    background-color: #ffffff;
}

.certificate-wrapper {
    width: 100%;
    min-height: 700px;
    box-sizing: border-box;
    padding: 30px;
    background-color: #ffffff;
    border: 15px solid #1e3a8a;
    position: relative;
    font-family: 'Montserrat', sans-serif;
}

.certificate-inner {
    border: 3px solid #d97706;
    padding: 40px;
    min-height: 600px;
    box-sizing: border-box;
    position: relative;
    text-align: center;
    background-color: #f8fafc;
}

.cert-header {
    margin-top: 10px;
    margin-bottom: 30px;
}

.cert-logo {
    max-height: 60px;
}

.cert-brand {
    font-size: 28px;
    font-weight: 800;
    color: #1e3a8a;
    letter-spacing: 2px;
    text-transform: uppercase;
}

.cert-title {
    font-size: 38px;
    font-weight: 800;
    color: #1e3a8a;
    letter-spacing: 4px;
    margin-bottom: 20px;
}

.cert-subtitle {
    font-size: 16px;
    color: #4b5563;
    margin-bottom: 20px;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.cert-name {
    font-family: 'Playfair Display', serif;
    font-size: 52px;
    font-style: italic;
    color: #1e40af;
    margin-bottom: 30px;
    border-bottom: 2px solid #d97706;
    display: inline-block;
    padding-bottom: 10px;
    min-width: 60%;
}

.cert-body {
    font-size: 18px;
    color: #374151;
    line-height: 1.6;
    margin-bottom: 40px;
    width: 80%;
    margin-left: auto;
    margin-right: auto;
}

.cert-course {
    display: block;
    font-size: 26px;
    font-weight: 600;
    color: #1e3a8a;
    margin: 10px 0;
}

.cert-date {
    font-weight: 600;
    color: #111827;
}

.cert-footer {
    margin-top: 40px;
    width: 100%;
}

.signature-line {
    border-top: 1px solid #9ca3af;
    width: 80%;
    margin: 0 auto 10px auto;
}

.signature-title {
    font-size: 14px;
    font-weight: 600;
    color: #4b5563;
}

.cert-badge {
    width: 90px;
    height: 90px;
    background-color: #d97706;
    border-radius: 50%;
    margin: 0 auto;
    position: relative;
    border: 3px solid #fcd34d;
}

.badge-inner {
    width: 76px;
    height: 76px;
    background-color: #1e3a8a;
    border-radius: 50%;
    position: absolute;
    top: 4px;
    left: 4px;
    color: white;
    font-family: 'Montserrat', sans-serif;
    text-align: center;
}
